#include <unordered_map>
using namespace std;

string minWindow(string s, string t) {
    unordered_map<char, int> tFreq, windowFreq;
    int required = t.size();
    int left = 0, right = 0;
    int minLeft = 0, minLength = s.size() + 1;

    for (char ch : t) tFreq[ch]++;

    while (right < s.size()) {
        // Expand the window to the right
        windowFreq[s[right]]++;
        if (tFreq.count(s[right]) && windowFreq[s[right]] <= tFreq[s[right]]) {
            required--;
        }

        // Shrink the window from the left
        while (required == 0 && left <= right) {
            if (right - left + 1 < minLength) {
                minLength = right - left + 1;
                minLeft = left;
            }
            windowFreq[s[left]]--;
            if (tFreq.count(s[left]) && windowFreq[s[left]] < tFreq[s[left]]) {
                required++;
            }
            left++;
        }

        right++;
    }

    if (minLength > s.size()) {
        return "";
    } else {
        return s.substr(minLeft, minLength);
    }
}

int main() {
    string s = "ADOBECODEBANC";
    string t = "ABC";
    cout << minWindow(s, t) << endl;
    return 0;
}
```

The `minWindow` function takes two strings `s` and `t` as input and returns the minimum window in `s` that contains all the characters in `t`. The function first creates two frequency maps: `tFreq` to store the frequency of characters in the target string `t` and `windowFreq` to store the frequency of characters in the current window. The function then uses two pointers `left` and `right` to create a sliding window on string `s`. The `required` variable stores how many characters from `t` are still needed in the window. 

The function first expands the window to the right and updates the frequency counts in the `windowFreq` map. If the added character is in `t`, its frequency count is compared against the frequency count in the `tFreq` map, and if they match, `required` is decremented. 

The function then shrinks the window from the left until `required` becomes zero. The `minLength` variable stores the minimum length seen so far, and `minLeft` stores the starting index of the minimum window. If the current window is shorter than `minLength`, update `minLength` and `minLeft`. 

Finally, the function returns an empty string if no valid window was found, otherwise it returns the substring of length `minLength` starting at index `minLeft`. 

In this example, `minWindow("ADOBECODEBANC", "ABC")` returns `"BANC"`.
